<script setup lang="ts">
import { ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, CircleAlert, CircleHelp, Clock3, PackageCheck, Plus, RefreshCw, Repeat2, Search, ShoppingBag, Sparkles, UserPlus, Users, Wallet, X } from '@lucide/vue';
const route=useRoute(); const router=useRouter(); const config=useRuntimeConfig(); const session=useB2BSession(); const {openContextMenu,copyText}=useContextMenu();
const profile=ref<any>(null),dashboard=ref<any>({}),clients=ref<any[]>([]),services=ref<any[]>([]),bookings=ref<any[]>([]),catalog=ref<any[]>([]),orders=ref<any[]>([]),tickets=ref<any[]>([]); const loading=ref(true),saving=ref(false),error=ref(''),notice=ref(''),dialog=ref(''); const search=ref(''); const cart=reactive<Record<string,number>>({}); const draft=reactive<any>({});
const section=computed(()=>String(route.query.section||'dashboard')); const headers=computed(()=>({Authorization:`Bearer ${session.token.value}`}));
const titles:any={dashboard:['ЦЕНТР УПРАВЛЕНИЯ','Обзор бизнеса','Главное о салоне, клиентах, записи и закупках'],calendar:['РАБОЧИЙ КАЛЕНДАРЬ','Записи','Расписание клиентов и загрузка команды'],clients:['КЛИЕНТСКАЯ БАЗА','Мои клиенты','История посещений, контакты и заметки'],services:['ПРАЙС-ЛИСТ','Услуги и цены','Продолжительность, стоимость и доступность услуг'],catalog:['ПАРТНЁРСКИЙ КАТАЛОГ','Закупить товары','Персональные B2B-цены и актуальные остатки 1С'],orders:['ИСТОРИЯ ЗАКУПОК','Мои заказы','Статусы, состав и быстрый повтор заказа'],team:['ОРГАНИЗАЦИЯ','Команда','Сотрудники и права в кабинете'],support:['ПОМОЩЬ БИЗНЕСУ','Поддержка','Обращения к команде Sarkisian и контроль ответов']};
const currentTitle=computed(()=>titles[section.value]||titles.dashboard); const money=(v:any)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(Number(v||0)); const dateTime=(v:any)=>new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}); const statusLabels:any={NEW:'Новая',CONFIRMED:'Подтверждена',COMPLETED:'Завершена',CANCELLED:'Отменена',NO_SHOW:'Не пришёл',PAYMENT_WAITING:'Ожидает оплаты',PAID:'Оплачен',ASSEMBLING:'Собирается',SHIPPED:'Отправлен',DELIVERED:'Доставлен',REFUNDED:'Возврат',OPEN:'В работе',WAITING_CUSTOMER:'Ждём ответ',WAITING_INTERNAL:'На уточнении',RESOLVED:'Решена',CLOSED:'Закрыта'};
function fulfillmentLabel(item:any){if(item.oneCSyncError)return 'Ошибка передачи';if(item.packedAt)return 'Упакован';if(item.pickedAt)return 'Товар отобран';if(item.pickingStartedAt)return 'Собирается на складе';if(item.isSynced1C)return 'Передан в 1С';return 'В очереди 1С'}
const filteredClients=computed(()=>{const q=search.value.toLowerCase();return clients.value.filter(x=>`${x.firstName} ${x.lastName||''} ${x.phone||''} ${x.email||''}`.toLowerCase().includes(q))});
const cartLines=computed(()=>catalog.value.flatMap(p=>p.variants.filter((v:any)=>cart[v.id]).map((v:any)=>({product:p,variant:v,quantity:cart[v.id]})))); const cartTotal=computed(()=>cartLines.value.reduce((s,l)=>s+l.variant.b2bPrice*l.quantity,0));
async function api<T>(path:string,options:any={}){return $fetch<T>(path,{baseURL:config.public.apiBase,headers:headers.value,...options})}
async function load(){loading.value=true;error.value='';try{const result=await Promise.all([api<any>('/b2b/profile'),api<any>('/b2b/dashboard'),api<any[]>('/b2b/clients'),api<any[]>('/b2b/services'),api<any[]>('/b2b/bookings'),api<any[]>('/b2b/catalog'),api<any[]>('/b2b/orders'),api<any[]>('/b2b/support')]);[profile.value,dashboard.value,clients.value,services.value,bookings.value,catalog.value,orders.value,tickets.value]=result}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить кабинет'}finally{loading.value=false}}
function flash(v:string){notice.value=v;setTimeout(()=>notice.value='',2500)} function open(type:string,value:any={}){dialog.value=type;Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,value)} function close(){dialog.value='';error.value=''}
async function saveClient(){saving.value=true;try{await api('/b2b/clients',{method:'POST',body:{firstName:draft.firstName,lastName:draft.lastName||undefined,phone:draft.phone||undefined,email:draft.email||undefined,notes:draft.notes||undefined,tags:String(draft.tags||'').split(',').map(x=>x.trim()).filter(Boolean),personalDataConsent:Boolean(draft.personalDataConsent)}});close();await load();flash('Клиент добавлен')}catch(e:any){error.value=e?.data?.message||'Не удалось добавить клиента'}finally{saving.value=false}}
async function saveService(){saving.value=true;try{await api('/b2b/services',{method:'POST',body:{name:draft.name,description:draft.description||undefined,duration:Number(draft.duration),price:Number(draft.price),color:draft.color||'#f8604a'}});close();await load();flash('Услуга добавлена')}catch(e:any){error.value=e?.data?.message||'Не удалось добавить услугу'}finally{saving.value=false}}
async function saveBooking(){saving.value=true;try{await api('/b2b/bookings',{method:'POST',body:{clientId:draft.clientId,serviceId:draft.serviceId,masterMemberId:draft.masterMemberId||undefined,startTime:new Date(draft.startTime).toISOString(),notes:draft.notes||undefined}});close();await load();flash('Запись создана')}catch(e:any){error.value=e?.data?.message||'Не удалось создать запись'}finally{saving.value=false}}
async function bookingStatus(item:any,status:string){await api(`/b2b/bookings/${item.id}`,{method:'PATCH',body:{status}});await load();flash(status==='COMPLETED'?'Визит завершён':'Статус записи обновлён')}
async function checkout(){if(!cartLines.value.length)return;saving.value=true;try{const order:any=await api('/b2b/orders',{method:'POST',body:{items:cartLines.value.map(l=>({variantId:l.variant.id,quantity:l.quantity}))}});Object.keys(cart).forEach(k=>delete cart[k]);close();await load();flash(`Заказ ${order.orderNumber} создан`);router.push('/b2b?section=orders')}catch(e:any){error.value=e?.data?.message||'Не удалось оформить заказ'}finally{saving.value=false}}
async function repeatOrder(item:any){await api(`/b2b/orders/${item.id}/repeat`,{method:'POST'});await load();flash('Повторный заказ создан')}
async function saveSupport(){saving.value=true;try{await api('/b2b/support',{method:'POST',body:{subject:draft.subject,description:draft.description,priority:draft.priority||'MEDIUM'}});close();await load();flash('Обращение отправлено')}catch(e:any){error.value=e?.data?.message||'Не удалось отправить обращение'}finally{saving.value=false}}
function clientMenu(e:MouseEvent,item:any){openContextMenu(e,`${item.firstName} ${item.lastName||''}`,[{label:'Создать запись',icon:'open',action:()=>open('booking',{clientId:item.id})},{label:'Копировать телефон',icon:'copy',action:()=>copyText(item.phone||'','Телефон скопирован')}],item.phone||item.email||'Клиент')}
function orderMenu(e:MouseEvent,item:any){openContextMenu(e,item.orderNumber,[{label:'Повторить заказ',icon:'copy',action:()=>repeatOrder(item)},{label:'Копировать номер',icon:'copy',action:()=>copyText(item.orderNumber,'Номер заказа скопирован')}],statusLabels[item.status]||item.status)}
onMounted(async()=>{
  session.hydrate();
  if(!session.token.value)return navigateTo('/b2b-login');
  const restored=await session.restore();
  if(!restored)return navigateTo('/b2b-login');
  await load();
});
</script>

<template><main class="portal"><header class="top"><div><p>{{currentTitle[0]}}</p><h1>{{currentTitle[1]}}</h1><span>{{currentTitle[2]}}</span></div><div class="top-actions"><button @click="load"><RefreshCw :size="15"/>Обновить</button><button v-if="section==='clients'" class="primary" @click="open('client')"><UserPlus :size="15"/>Новый клиент</button><button v-else-if="section==='calendar'" class="primary" @click="open('booking')"><Plus :size="15"/>Новая запись</button><button v-else-if="section==='services'" class="primary" @click="open('service',{duration:60,color:'#f8604a'})"><Plus :size="15"/>Новая услуга</button><button v-else-if="section==='support'" class="primary" @click="open('support',{priority:'MEDIUM'})"><Plus :size="15"/>Обращение</button><button v-else-if="section==='catalog'" class="primary" @click="open('cart')"><ShoppingBag :size="15"/>Корзина · {{cartLines.length}}</button></div></header><div v-if="loading" class="loading">Загружаем рабочее пространство…</div><p v-else-if="error&&!dialog" class="page-error"><CircleAlert :size="16"/>{{error}}</p><section v-else class="body">

<template v-if="section==='dashboard'"><div class="hero"><div><p>SARKISIAN BUSINESS</p><h2>{{profile?.name}}</h2><span>Скидка партнёра {{profile?.discountTier||0}}% · {{profile?.status==='ACTIVE'?'организация активна':'профиль на модерации'}}</span></div><div><b>{{dashboard.bookingsToday||0}}</b><span>записей сегодня</span></div></div><div class="kpis"><article><span>Клиенты</span><b>{{dashboard.clients||0}}</b><small>в активной базе</small></article><article><span>Будущие записи</span><b>{{dashboard.upcoming||0}}</b><small>ожидают визита</small></article><article><span>Выручка услуг</span><b>{{money(dashboard.serviceRevenueMonth)}}</b><small>за текущий месяц</small></article><article><span>Закупки</span><b>{{money(dashboard.purchasesMonth)}}</b><small>{{dashboard.purchaseOrdersMonth||0}} заказов за месяц</small></article></div><div class="dashboard-grid"><article class="panel"><header><div><p>БЛИЖАЙШЕЕ</p><h3>Следующие записи</h3></div><NuxtLink to="/b2b?section=calendar">Весь календарь <ArrowRight :size="14"/></NuxtLink></header><div v-for="item in dashboard.nextBookings" :key="item.id" class="agenda"><time>{{dateTime(item.startTime)}}</time><i :style="{background:item.service.color}"></i><span><b>{{item.client.firstName}} {{item.client.lastName}}</b><small>{{item.service.name}} · {{item.service.duration}} мин.</small></span><em>{{statusLabels[item.status]}}</em></div><div v-if="!dashboard.nextBookings?.length" class="empty">Ближайших записей нет</div></article><article class="panel"><header><div><p>ЗАКУПКИ</p><h3>Последние заказы</h3></div><NuxtLink to="/b2b?section=catalog">В каталог <ArrowRight :size="14"/></NuxtLink></header><div v-for="item in dashboard.recentOrders" :key="item.id" class="order-mini"><span><b>{{item.orderNumber}}</b><small>{{new Date(item.createdAt).toLocaleDateString('ru-RU')}} · {{item.items.length}} позиций</small></span><em>{{money(item.finalAmount)}}</em></div><div v-if="!dashboard.recentOrders?.length" class="empty">Заказов пока нет</div></article></div><div class="quick"><button @click="router.push('/b2b?section=calendar')"><CalendarDays/><span><b>Управлять записью</b><small>Календарь и загрузка мастеров</small></span><ArrowRight/></button><button @click="router.push('/b2b?section=clients')"><Users/><span><b>Клиентская база</b><small>Контакты и история визитов</small></span><ArrowRight/></button><button @click="router.push('/b2b?section=catalog')"><PackageCheck/><span><b>Пополнить материалы</b><small>{{dashboard.lowStock||0}} позиций требуют внимания</small></span><ArrowRight/></button></div></template>

<template v-else-if="section==='clients'"><article class="panel list-panel"><header><div><p>БАЗА САЛОНА</p><h3>{{clients.length}} клиентов</h3></div><label class="search"><Search :size="15"/><input v-model="search" placeholder="Имя, телефон или email"/></label></header><div class="table clients"><div class="row labels"><span>Клиент</span><span>Контакты</span><span>Последний визит</span><span>Посещения</span><span>Сумма услуг</span></div><div v-for="item in filteredClients" :key="item.id" class="row" @contextmenu.prevent="clientMenu($event,item)"><span class="client"><i>{{item.firstName.slice(0,1)}}</i><span><b>{{item.firstName}} {{item.lastName}}</b><small>{{item.tags?.join(', ')||'Без тегов'}}</small></span></span><span>{{item.phone||item.email||'Не указаны'}}</span><span>{{item.lastVisitAt?new Date(item.lastVisitAt).toLocaleDateString('ru-RU'):'Ещё не был'}}</span><span>{{item.totalVisits}}</span><b>{{money(item.totalSpent)}}</b></div><div v-if="!filteredClients.length" class="empty">Добавьте первого клиента — его история будет собираться автоматически.</div></div></article></template>

<template v-else-if="section==='calendar'"><div class="calendar-tools"><button><ChevronLeft :size="16"/></button><div><b>Ближайшие записи</b><span>{{bookings.length}} в календаре</span></div><button><ChevronRight :size="16"/></button><i></i><button class="active">Список</button><button>Неделя</button><button>Месяц</button></div><article class="panel booking-list"><div v-for="item in bookings" :key="item.id" class="booking"><time><b>{{new Date(item.startTime).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}}</b><small>{{new Date(item.startTime).toLocaleDateString('ru-RU',{day:'2-digit',month:'short'})}}</small></time><i :style="{background:item.service.color}"></i><span class="booking-main"><b>{{item.client.firstName}} {{item.client.lastName}}</b><small>{{item.service.name}} · {{item.service.duration}} минут · {{money(item.service.price)}}</small></span><span class="master">{{item.masterMember?[item.masterMember.user.firstName,item.masterMember.user.lastName].filter(Boolean).join(' '):'Мастер не назначен'}}</span><em :class="item.status.toLowerCase()">{{statusLabels[item.status]}}</em><div><button v-if="!['COMPLETED','CANCELLED'].includes(item.status)" title="Завершить" @click="bookingStatus(item,'COMPLETED')"><Check :size="15"/></button><button v-if="!['COMPLETED','CANCELLED'].includes(item.status)" title="Отменить" @click="bookingStatus(item,'CANCELLED')"><X :size="15"/></button></div></div><div v-if="!bookings.length" class="empty">Календарь свободен. Создайте первую запись.</div></article></template>

<template v-else-if="section==='services'"><div class="service-grid"><article v-for="item in services" :key="item.id" class="service"><i :style="{background:item.color}"></i><span><small>{{item.isActive?'ДОСТУПНА':'ВЫКЛЮЧЕНА'}}</small><h3>{{item.name}}</h3><p>{{item.description||'Описание услуги не задано'}}</p></span><footer><b>{{money(item.price)}}</b><em><Clock3 :size="14"/>{{item.duration}} мин.</em></footer></article><button class="add-card" @click="open('service',{duration:60,color:'#f8604a'})"><Plus :size="23"/><b>Добавить услугу</b><span>Настройте цену и длительность</span></button></div></template>

<template v-else-if="section==='catalog'"><div class="catalog-layout"><div class="product-grid"><article v-for="product in catalog" :key="product.id" class="product"><div class="product-image"><img v-if="product.images?.[0]?.url&&!product.images[0].url.startsWith('/catalog/')" :src="product.images[0].url" :alt="product.nameRu"/><Sparkles v-else :size="25"/></div><span><small>{{product.sku}}</small><h3>{{product.nameRu}}</h3></span><div v-for="variant in product.variants" :key="variant.id" class="variant"><span><s v-if="variant.b2bPrice!==variant.retailPrice">{{money(variant.retailPrice)}}</s><b>{{money(variant.b2bPrice)}}</b><small>доступно {{variant.available}}</small></span><div><button @click="cart[variant.id]=Math.max(0,(cart[variant.id]||0)-1)">−</button><b>{{cart[variant.id]||0}}</b><button :disabled="(cart[variant.id]||0)>=variant.available" @click="cart[variant.id]=(cart[variant.id]||0)+1">+</button></div></div></article></div><aside class="cart-summary"><p>ВАШ ЗАКАЗ</p><h3>{{cartLines.length?`${cartLines.length} позиций`:'Корзина пуста'}}</h3><div v-for="line in cartLines" :key="line.variant.id"><span>{{line.product.nameRu}}<small>{{line.quantity}} × {{money(line.variant.b2bPrice)}}</small></span><b>{{money(line.quantity*line.variant.b2bPrice)}}</b></div><footer><span>Итого<b>{{money(cartTotal)}}</b></span><button :disabled="!cartLines.length" @click="open('cart')">Оформить заказ <ArrowRight :size="15"/></button></footer></aside></div></template>

<template v-else-if="section==='orders'"><article class="panel list-panel"><header><div><p>ЕДИНЫЙ OMS</p><h3>{{orders.length}} заказов</h3></div><span class="info">Заказ сразу передаётся в 1С и появляется у кладовщика на ТСД.</span></header><div class="table orders"><div class="row labels"><span>Заказ</span><span>Дата</span><span>Состав</span><span>Статус</span><span>Склад</span><span>Сумма</span><span></span></div><div v-for="item in orders" :key="item.id" class="row" @contextmenu.prevent="orderMenu($event,item)"><b>{{item.orderNumber}}</b><span>{{new Date(item.createdAt).toLocaleDateString('ru-RU')}}</span><span>{{item.items.length}} позиций</span><em :class="item.status.toLowerCase()">{{statusLabels[item.status]||item.status}}</em><span :class="item.oneCSyncError?'sync-error':'sync-state'">{{fulfillmentLabel(item)}}</span><b>{{money(item.finalAmount)}}</b><button @click="repeatOrder(item)"><Repeat2 :size="14"/>Повторить</button></div><div v-if="!orders.length" class="empty">Заказов пока нет. Перейдите в каталог, чтобы оформить первую закупку.</div></div></article></template>

<template v-else-if="section==='team'"><div class="team-head"><div><p>ВАША ОРГАНИЗАЦИЯ</p><h2>{{profile.name}}</h2><span>ИНН {{profile.inn||'не указан'}} · {{profile.legalAddress||'адрес не указан'}}</span></div><div><span>Уровень скидки<b>{{profile.discountTier||0}}%</b></span><span>Лимит закупок<b>{{money(profile.creditLimit)}}</b></span></div></div><div class="team-grid"><article v-for="item in profile.members" :key="item.id"><i>{{(item.user.firstName||item.user.email).slice(0,1)}}</i><span><b>{{[item.user.firstName,item.user.lastName].filter(Boolean).join(' ')||item.user.email}}</b><small>{{item.user.email}}</small></span><em>{{item.role==='OWNER'?'Владелец':item.role==='BUYER'?'Закупщик':item.role==='ACCOUNTANT'?'Бухгалтер':'Сотрудник'}}</em></article></div></template>

<template v-else-if="section==='support'"><div class="support-intro"><CircleHelp :size="28"/><div><p>ПЕРСОНАЛЬНАЯ ПОДДЕРЖКА</p><h2>Мы рядом с вашим бизнесом</h2><span>Вопросы по заказам, товарам, обучению и работе кабинета попадут в единый Helpdesk.</span></div><button @click="open('support',{priority:'MEDIUM'})">Создать обращение</button></div><article class="panel list-panel"><header><div><p>МОИ ОБРАЩЕНИЯ</p><h3>{{tickets.length}} заявок</h3></div></header><div class="table tickets"><div class="row labels"><span>Номер</span><span>Тема</span><span>Приоритет</span><span>Статус</span><span>Создано</span></div><div v-for="item in tickets" :key="item.id" class="row"><b>{{item.number}}</b><span>{{item.subject}}</span><span>{{item.priority==='CRITICAL'?'Критичный':item.priority==='HIGH'?'Высокий':item.priority==='LOW'?'Низкий':'Обычный'}}</span><em>{{statusLabels[item.status]||item.status}}</em><span>{{new Date(item.createdAt).toLocaleDateString('ru-RU')}}</span></div><div v-if="!tickets.length" class="empty">Обращений пока нет.</div></div></article></template>
</section>

<div v-if="dialog" class="backdrop" @click.self="close"><form class="drawer" @submit.prevent="dialog==='client'?saveClient():dialog==='service'?saveService():dialog==='booking'?saveBooking():dialog==='support'?saveSupport():checkout()"><header><div><p>{{dialog==='client'?'КЛИЕНТСКАЯ БАЗА':dialog==='service'?'ПРАЙС-ЛИСТ':dialog==='booking'?'КАЛЕНДАРЬ':dialog==='support'?'HELPDESK':'ЗАКУПКА'}}</p><h2>{{dialog==='client'?'Новый клиент':dialog==='service'?'Новая услуга':dialog==='booking'?'Новая запись':dialog==='support'?'Новое обращение':'Подтверждение заказа'}}</h2></div><button type="button" @click="close"><X :size="18"/></button></header><div class="drawer-body">
<template v-if="dialog==='client'"><div class="two"><label>Имя<input v-model="draft.firstName" required/></label><label>Фамилия<input v-model="draft.lastName"/></label></div><label>Телефон<input v-model="draft.phone" placeholder="+7 900 000-00-00"/></label><label>Email<input v-model="draft.email" type="email"/></label><label>Теги через запятую<input v-model="draft.tags" placeholder="VIP, маникюр"/></label><label>Заметки<textarea v-model="draft.notes" rows="4"/></label><label class="check"><input v-model="draft.personalDataConsent" type="checkbox"/><span><b>Согласие на обработку данных получено</b><small>Зафиксировать согласие клиента в карточке</small></span></label></template>
<template v-else-if="dialog==='service'"><label>Название<input v-model="draft.name" required/></label><label>Описание<textarea v-model="draft.description" rows="4"/></label><div class="two"><label>Длительность, минут<input v-model.number="draft.duration" type="number" min="10" required/></label><label>Цена, ₽<input v-model.number="draft.price" type="number" min="0" required/></label></div><label>Цвет в календаре<input v-model="draft.color" type="color"/></label></template>
<template v-else-if="dialog==='booking'"><label>Клиент<select v-model="draft.clientId" required><option value="" disabled>Выберите клиента</option><option v-for="item in clients" :value="item.id">{{item.firstName}} {{item.lastName}}</option></select></label><label>Услуга<select v-model="draft.serviceId" required><option value="" disabled>Выберите услугу</option><option v-for="item in services.filter(x=>x.isActive)" :value="item.id">{{item.name}} · {{item.duration}} мин.</option></select></label><label>Мастер<select v-model="draft.masterMemberId"><option value="">Не назначать</option><option v-for="item in profile.members" :value="item.id">{{item.user.firstName}} {{item.user.lastName}}</option></select></label><label>Дата и время<input v-model="draft.startTime" type="datetime-local" required/></label><label>Комментарий<textarea v-model="draft.notes" rows="3"/></label></template>
<template v-else-if="dialog==='support'"><label>Тема<input v-model="draft.subject" required/></label><label>Приоритет<select v-model="draft.priority"><option value="LOW">Низкий</option><option value="MEDIUM">Обычный</option><option value="HIGH">Высокий</option><option value="CRITICAL">Критичный</option></select></label><label>Опишите вопрос<textarea v-model="draft.description" rows="7" required/></label></template>
<template v-else><div class="checkout-lines"><div v-for="line in cartLines"><span>{{line.product.nameRu}}<small>{{line.quantity}} шт.</small></span><b>{{money(line.quantity*line.variant.b2bPrice)}}</b></div></div><div class="checkout-total"><span>К оплате</span><b>{{money(cartTotal)}}</b></div><p class="checkout-note">Заказ создаётся в едином OMS, сразу передаётся в 1С и поступает кладовщику на ТСД.</p></template>
<p v-if="error" class="form-error">{{error}}</p></div><footer><button type="button" @click="close">Отмена</button><button class="primary" :disabled="saving">{{saving?'Сохраняем…':dialog==='cart'?'Оформить заказ':'Сохранить'}}</button></footer></form></div><div v-if="notice" class="toast">{{notice}}</div></main></template>

